export interface DlqDeps {
  queueName: string;
  archive: (record: SQSRecord) => Promise<void>;
}

export function makeDlqConsumer(deps: DlqDeps) {
  return async function handle(records: SQSRecord[]): Promise<void> {
    for (const record of records) {
      await deps.archive(record);
      logger.error(
        { queue: deps.queueName, messageId: record.messageId },
        "gave up on message, archived",
      );
    }
  };
}

