export class AppError extends Error {
  constructor(message: string, readonly code: string, readonly cause?: unknown) {
    super(message);
    this.name = new.target.name;
  }
}

export class NotFoundError extends AppError {
  constructor(what: string) {
    super(`${what} not found`, "NOT_FOUND");
  }
}

export class UpstreamError extends AppError {
  constructor(service: string, cause: unknown) {
    super(`${service} request failed`, "UPSTREAM", cause);
  }
}

export class ForbiddenError extends AppError {
  constructor(message: string) {
    super(message, "FORBIDDEN");
  }
}

import { DynamoDBDocumentClient, GetCommand, PutCommand } from "@aws-sdk/lib-dynamodb";
import { NotFoundError, UpstreamError } from "../errors";

export interface Session {
  sessionId: string;
  userId: string;
  startedAt: string;
}

export class SessionStore {
  constructor(private readonly doc: DynamoDBDocumentClient, private readonly table: string) {}

  async get(sessionId: string): Promise<Session> {
    let res;
    try {
      res = await this.doc.send(new GetCommand({ TableName: this.table, Key: { sessionId } }));
    } catch (err) {
      throw new UpstreamError("dynamodb", err);
    }
    if (!res.Item) throw new NotFoundError(`session ${sessionId}`);
    return res.Item as Session;
  }

  async put(session: Session): Promise<void> {
    try {
      await this.doc.send(new PutCommand({ TableName: this.table, Item: session }));
    } catch (err) {
      throw new UpstreamError("dynamodb", err);
    }
  }
}

import { SessionStore } from "../db/sessions";
import { Tool } from "./tool";

export interface RunToolDeps {
  sessions: SessionStore;
  tools: Map<string, Tool>;
}

export async function runTool(
  deps: RunToolDeps,
  sessionId: string,
  name: string,
  input: unknown,
): Promise<string> {
  const session = await deps.sessions.get(sessionId);
  const tool = deps.tools.get(name);
  if (!tool) return JSON.stringify({ error: `unknown tool ${name}` });
  const output = await tool.run({ userId: session.userId }, input);
  return JSON.stringify(output);
}

