import { SendMessageCommand, SQSClient } from "@aws-sdk/client-sqs";
import { config } from "../config";
import { Priority } from "./priority";

function assertNever(x: never): never {
  throw new Error(`unhandled priority ${String(x)}`);
}

function queueFor(priority: Priority): string {
  switch (priority) {
    case "low":
      return config.lowQueueUrl;
    case "normal":
      return config.normalQueueUrl;
    case "urgent":
      return config.urgentQueueUrl;
    default:
      return assertNever(priority);
  }
}

export async function enqueueJob(
  sqs: SQSClient,
  priority: Priority,
  job: { type: string; payload: unknown },
): Promise<void> {
  await sqs.send(
    new SendMessageCommand({
      QueueUrl: queueFor(priority),
      MessageBody: JSON.stringify(job),
    }),
  );
}

