import logging

log = logging.getLogger(__name__)
MAX_BODY_BYTES = 256 * 1024


def handler(event, context):
    body = event.get("body") or ""
    if len(body.encode("utf-8")) > MAX_BODY_BYTES:
        log.warning("webhook body too large")
        return {"statusCode": 413, "body": json.dumps({"message": "payload too large"})}
    try:
        data = json.loads(body)
    except json.JSONDecodeError:
        return {"statusCode": 400, "body": json.dumps({"message": "invalid json"})}
    if not data.get("tenant_id"):
        return {"statusCode": 400, "body": json.dumps({"message": "tenant_id required"})}

    # external senders: signature already verified by the API Gateway authorizer
    enqueue_ingest(data["tenant_id"], data)
    return {"statusCode": 202, "body": json.dumps({"accepted": True})}


def enqueue_ingest(tenant_id: str, data: dict) -> None:
    from lambdas.queueing import send

    send("ingest", {"tenant_id": tenant_id, "data": data})

import logging
import random
import time
from typing import Callable, TypeVar

T = TypeVar("T")
log = logging.getLogger(__name__)


def retry(
    fn: Callable[[], T],
    *,
    attempts: int = 3,
    base_delay: float = 0.5,
    retry_on: tuple[type[BaseException], ...] = (Exception,),
    is_retryable: Callable[[BaseException], bool] = lambda e: True,
    sleep: Callable[[float], None] = time.sleep,
) -> T:
    """Call fn, retrying with exponential backoff and jitter."""
    for attempt in range(1, attempts + 1):
        try:
            return fn()
        except retry_on as exc:
            if attempt == attempts or not is_retryable(exc):
                raise
            delay = base_delay * (2 ** (attempt - 1)) * (0.5 + random.random())
            log.warning("retrying after %s (attempt %d/%d)", exc, attempt, attempts)
            sleep(delay)
    raise AssertionError("unreachable")

