class EmbeddingClient:
    def __init__(self, bedrock_runtime, model_id: str):
        self._bedrock = bedrock_runtime
        self._model_id = model_id

    def embed(self, text: str) -> list[float]:
        resp = self._bedrock.invoke_model(
            modelId=self._model_id,
            body=json.dumps({"inputText": text}),
        )
        return json.loads(resp["body"].read())["embedding"]

    def embed_batch(self, texts: list[str]) -> list[list[float]]:
        return [self.embed(t) for t in texts]

from app.embeddings.client import EmbeddingClient


def ingest_chunks(conn, client: EmbeddingClient, doc_id: str, chunks: list[str]) -> int:
    vectors = client.embed_batch(chunks)
    with conn.cursor() as cur:
        for i, (text, vec) in enumerate(zip(chunks, vectors)):
            cur.execute(
                "INSERT INTO chunks (doc_id, ord, body, embedding) VALUES (%s, %s, %s, %s)",
                (doc_id, i, text, vec),
            )
    conn.commit()
    return len(chunks)

export interface ToolContext {
  userId: string;
}

export interface Tool<I = any, O = unknown> {
  readonly name: string;
  readonly description: string;
  readonly inputSchema: object;
  run(ctx: ToolContext, input: I): Promise<O>;
  /** One line describing this call for the audit log. */
  auditLine(input: I): string;
}

import { Tool } from "../tool";
import { OrdersApi } from "../../clients/ordersApi";

export class GetOrderTool implements Tool<{ orderId: string }> {
  readonly name = "get_order";
  readonly description = "Look up an order by id.";
  readonly inputSchema = {
    type: "object",
    properties: { orderId: { type: "string" } },
    required: ["orderId"],
  };

  constructor(private readonly orders: OrdersApi) {}

  run(_ctx: unknown, input: { orderId: string }) {
    return this.orders.get(input.orderId);
  }

  auditLine(input: { orderId: string }): string {
    return `get_order orderId=${input.orderId}`;
  }
}

import { Tool, ToolContext } from "./tool";
import { logger } from "../logger";

export function makeDispatcher(tools: Tool[]) {
  const byName = new Map(tools.map((t) => [t.name, t]));

  return async function dispatch(ctx: ToolContext, name: string, input: unknown) {
    const tool = byName.get(name);
    if (!tool) throw new Error(`unknown tool ${name}`);
    logger.info({ userId: ctx.userId, call: tool.auditLine(input) }, "tool call");
    return tool.run(ctx, input);
  };
}

